import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ParallelFoldReducerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object guard(java.util.concurrent.Callable<Object> body) {
        try {
            return body.call();
        } catch (Exception e) {
            return "<threw " + e.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        List<String> words = Arrays.asList("ab", "cde", "f");

        check("totalLength([ab, cde, f])", 6, guard(() -> ParallelFoldReducer.totalLength(words)));
        check("totalLength(empty)", 0, guard(() -> ParallelFoldReducer.totalLength(Arrays.asList())));
        check("concatAll([ab, cde, f]) keeps order", "abcdef",
                guard(() -> ParallelFoldReducer.concatAll(words)));
        check("concatAll(empty)", "", guard(() -> ParallelFoldReducer.concatAll(Arrays.asList())));

        check("fold sums Integers", 10,
                guard(() -> ParallelFoldReducer.fold(Arrays.asList(1, 2, 3, 4), 0,
                        (sum, n) -> sum + n, (a, b) -> a + b)));
        check("fold returns the identity for an empty list", 99,
                guard(() -> ParallelFoldReducer.fold(new ArrayList<Integer>(), 99,
                        (sum, n) -> sum + n, (a, b) -> a + b)));
        check("fold can change type (list -> String)", "|1|2|3",
                guard(() -> ParallelFoldReducer.fold(Arrays.asList(1, 2, 3), "",
                        (text, n) -> text + "|" + n, (a, b) -> a + b)));

        List<Integer> big = new ArrayList<>();
        for (int i = 1; i <= 1000; i++) {
            big.add(i);
        }
        check("fold over 1000 elements in parallel", 500500,
                guard(() -> ParallelFoldReducer.fold(big, 0, (sum, n) -> sum + n, (a, b) -> a + b)));
        check("big list untouched", 1000, big.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
