import java.util.List;
import java.util.function.BiFunction;
import java.util.function.BinaryOperator;

/**
 * TASK: Implement the three-argument reduce -- identity, accumulator, combiner.
 *
 * fold(items, identity, accumulator, combiner) must reduce the list with
 *   items.parallelStream().reduce(identity, accumulator, combiner)
 * where:
 *   identity    is the starting value, and the answer for an empty list,
 *   accumulator folds ONE element into a partial result: (partial, element),
 *   combiner    merges TWO partial results: (partialA, partialB).
 * The combiner is the piece the two-argument reduce does not have; a parallel
 * stream splits the work and needs it to stitch the halves back together.
 *
 * Then use fold for:
 *   totalLength(words)  -- the sum of the word lengths, 0 for an empty list.
 *   concatAll(words)    -- every word glued together in list order.
 *
 * Example: totalLength(["ab", "cde"]) -> 5 ; concatAll(["ab", "cde"]) -> "abcde"
 */
public class ParallelFoldReducer {

    public static <T, R> R fold(List<T> items, R identity,
                                BiFunction<R, T, R> accumulator,
                                BinaryOperator<R> combiner) {
        return items.parallelStream().reduce(identity, accumulator, combiner);
    }

    public static int totalLength(List<String> words) {
        return fold(words, 0, (sum, word) -> sum + word.length(), (a, b) -> a + b);
    }

    public static String concatAll(List<String> words) {
        return fold(words, "", (text, word) -> text + word, (a, b) -> a + b);
    }
}
